from spec import *
X = []
X.append(AN("AN1b", 1, 1, "scheda", "Carducci, il socialismo, la scuola", [
 S("Il maestro", "Torniamo a Bologna, un passaggio decisivo. L'università di Bologna ha in cattedra Carducci. Sarà uno dei professori di Pascoli, e quello con cui si laurea. Il classicismo di Carducci influenza il giovane Pascoli ventenne. Pascoli resterà un classicista e un latinista. Ma nelle poesie la sua voce sarà diversa: niente stile solenne e magniloquente, e molta modernità. Carducci lo aiuterà anche con i primi incarichi di insegnamento.",
   [C("", "Carducci", "classicismo, tesi di laurea"), C("", "Pascoli poeta", "voce moderna, non solenne")]),
 S("Un giovane tra due fuochi", "Bologna è anche una città molto attiva dal punto di vista politico. Nel secondo Ottocento il socialismo si diffonde sempre di più, e Pascoli ne è affascinato. Si avvicina all'ideologia socialista e partecipa alle iniziative dei socialisti locali. Nel milleottocentosettantanove viene arrestato, per un breve periodo. Quindi in lui convivono due anime: il fascino della poesia classica di Carducci e l'impegno politico socialista.",
   [C("", "Socialismo", "ideologia che si diffonde nel secondo Ottocento"), C("1879", "Breve arresto", "attività politica")]),
 S("Dalla politica alla scuola", "Superato quel momento, Pascoli si dedica all'insegnamento. Come Carducci, insegna nei licei. Le materie sono quelle classiche, il latino e la letteratura. Alcuni incarichi lo portano lontano dalla Romagna. Per molti anni è soprattutto un professore di liceo. Solo nel millenovecentocinque, con la cattedra di Letteratura italiana a Bologna, diventa un professore universitario. Ha preso il posto del suo maestro.",
   [C("", "Insegnante", "licei, materie classiche"), C("1905", "Professore universitario", "cattedra di Letteratura italiana")])]))
X.append(AN("AN3b", 1, 3, "scheda", "Positivismo, scienza e mistero", [
 S("Oltre il Positivismo", "Vediamo la visione del mondo di Pascoli. Si forma durante la crisi del Positivismo. Molti, alla fine dell'Ottocento, non credono più alla magnificazione della scienza e del progresso. Pascoli ha un vivo interesse per le scienze e per l'astronomia. Ma non ne fa una nuova religione. Non crede che la scienza possa spiegare tutto. Anzi, sente più forte il mistero e l'ignoto che circonda l'esistenza umana.",
   [C("", "Crisi del Positivismo", "sfiducia nella scienza"), C("", "Il mistero", "perché si deve morire?")]),
 S("Un mondo frammentato", "Per Pascoli il mondo è frammentato, senza gerarchie precostituite. Gli oggetti non sono descritti solo per la loro realtà materiale. Diventano simboli. I dettagli quotidiani e naturali filtrano la soggettività e alludono a una realtà ignota. Il poeta-fanciullo non usa la logica. Percepisce accordi segreti, corrispondenze nascoste tra le cose. Anche il simbolismo, già presente nei poeti francesi, qui diventa un modo per evocare verità misteriose.",
   [C("", "Gli oggetti come simboli", "alludono a una realtà ignota"), C("", "Conoscenza intuitiva", "corrispondenze segrete tra le cose")]),
 S("Decadente e simbolista", "Pascoli è quindi un decadente e un simbolista. Avverte la fine delle certezze e le tristezze della sua epoca. Le domande che si pone sono filosofiche e poetiche: perché dobbiamo morire? Ma attenzione. Non è una questione di religione. È piuttosto un modo di guardare dentro di sé. La sua poesia nasce da qui. Per questo, come abbiamo visto, non aderisce all'estetismo, ma costruisce una poesia pura e disinteressata.",
   [C("", "Decadentismo", "crisi delle certezze"), C("", "Simbolismo", "gli oggetti evocano verità nascoste")])]))
X.append(AN("AN8b", 1, 4, "scheda", "Myricae: i temi e le piccole cose", [
 S("La vita dei campi", "Che cosa troviamo in Myricae? Pascoli canta le piccole cose della vita, in particolare la vita campestre. A lui piace il paesaggio della campagna. Parla della sua casa, delle sue emozioni e dei suoi ricordi. Più che delle persone, parla del mondo dei campi. Ma attenzione. Non è una descrizione realistica. La vita campestre è carica di significati simbolici.",
   [C("", "Vita campestre", "paesaggio, casa, ricordi"), C("", "Valore simbolico", "ogni dettaglio allude a qualcosa")]),
 S("Il lutto sotto la superficie", "Dietro la campagna c'è il dramma familiare. I simboli sono legati alla morte e al tormento per la scomparsa del padre. Myricae è una poesia emotiva e frammentaria, nata dal contatto con il ricordo. Il riferimento al nido e ai morti torna in molte liriche. Per capirle, bisogna ricordare il dieci agosto del milleottocentosessantasette.",
   [C("", "Morte e lutto", "il trauma della famiglia"), C("", "Poesia emotiva", "frammenti, ricordi")]),
 S("Dopo Myricae", "Nel millenovecentotré escono i Canti di Castelvecchio. C'è una continuità ideale con Myricae. Ma la misura lirica approfondisce temi più inquieti, morbosi e cosmici. Troviamo ancora campagna e simboli. Il tono però è più inquieto. Restano le soluzioni formali che abbiamo visto: onomatopee, fonosimbolismo, linguaggio analogico e sintassi frantumata.",
   [C("1891", "Myricae", "campagna e simboli"), C("1903", "Canti di Castelvecchio", "temi più inquieti e cosmici")])]))
# --- Parte 2
X.append(AN("AN1b", 2, 1, "scheda", "X Agosto: il significato dei simboli", [
 S("Tre immagini", "X Agosto parte da tre immagini. La prima è la notte di San Lorenzo, con le stelle cadenti. La seconda è una rondine che torna al suo tetto con il cibo per i piccoli, e viene uccisa. La terza è un uomo che torna a casa e viene ucciso: il padre di Pascoli. Il poeta crea un parallelismo tra la rondine e il padre. Entrambi cadono con le braccia o le ali tese, e questo ricorda l'immagine della crocifissione.",
   [C("", "San Lorenzo", "la notte delle stelle cadenti"), C("", "Rondine e padre", "parallelismo tra natura e uomo")]),
 S("Innocenti", "Perché l'immagine della croce? Perché richiama il sacrificio dell'innocente. La rondine è innocente. Sta portando il cibo ai suoi piccoli, che ora moriranno di fame. Il padre, quando cade, dice: Perdono. Ricorda le parole di Cristo sulla croce, secondo i Vangeli. Il docente nota però una cosa. Pascoli non scrive Dio, scrive Cielo. La tradizione cristiana qui diventa un modo per dare forza al dolore.",
   [C("", "Sacrificio", "l'innocente che cade"), C("", "Perdono", "ricorda le parole di Cristo")]),
 S("Un dolore cosmico", "Il nido dei rondinini e la casa del padre restano vuoti. Distrutti dal male, che è stato generato dall'uomo. La rondine è stata uccisa da un uomo. Il padre è stato ucciso da un altro uomo. La tragedia individuale si proietta su scala cosmica. Il fitto cadere di stelle diventa un pianto del cielo sulla terra. E la terra, nell'ultimo verso, è un atomo opaco del Male.",
   [C("", "Il nido vuoto", "pulcini e figlie senza il padre"), C("", "Atomo opaco del Male", "la terra vista dal cielo")])]))
X.append(AN("AN3b", 2, 2, "parole", "Come si legge una poesia di Pascoli", [
 S("Segni da cercare", "Prima di leggere una poesia di Pascoli, impariamo a cercare alcuni segni. Il primo è il simbolo. Un uccello, un fiore o un oggetto quotidiano non sono solo descrizioni: alludono a una realtà nascosta. Il secondo è l'analogia. Pascoli accosta le immagini per somiglianza e lascia al lettore il compito di capire. Il terzo è la frantumazione. I legami logici si spezzano, e la frase diventa un insieme di impressioni.",
   [C("", "Simbolo", "un dettaglio che allude a un'altra realtà"), C("", "Analogia", "immagini accostate per somiglianza"), C("", "Frantumazione", "frasi spezzate, legami logici annullati")]),
 S("Suoni e temi", "Poi ci sono i suoni. Onomatopee e fonosimbolismo riproducono il significato profondo delle cose attraverso il suono delle parole. Pensiamo al verso monotono dell'assiuolo. Infine i temi. Le poesie del Pascoli raccontano sempre qualcosa che ritorna, il lutto, la morte, il nido. Il lettore attento li riconosce sotto la superficie della natura. Con questi quattro strumenti, ogni testo diventa più chiaro.",
   [C("", "Suono", "onomatopee e fonosimbolismo"), C("", "Tema", "lutto, morte, nido")])]))
X.append(AN("AN6b", 2, 3, "scheda", "Il gelsomino notturno: la notte di nozze", [
 S("La festa è finita", "Il gelsomino notturno fu scritta per le nozze di un amico. Pascoli descrive la notte in cui si compie l'unione dei due sposi. La festa è finita, gli invitati sono andati via. La casa rimane sola, e gli sposi vivono la loro prima notte. L'evento umano viene proiettato sugli elementi della natura. Si aprono i fiori del gelsomino al crepuscolo, volano le farfalle notturne, e dalla casa viene un bisbiglio.",
   [C("", "La casa nuziale", "festa finita, prima notte"), C("", "I fiori che si aprono", "crepuscolo, farfalle notturne")]),
 S("Il poeta fuori dalla casa", "Il poeta guarda la scena da fuori. Resta in una condizione di isolamento e di fedeltà assoluta al nido dei propri morti. Mentre nella casa si consuma l'atto d'amore, all'esterno l'erba cresce sulle tombe. I fiori esalano un profumo che sa di morte e di vita insieme. Pascoli è felice per gli altri, ma ricorda sempre che si deve morire. Il tormento del passato lo tiene fuori dal ciclo della vita.",
   [C("", "Esclusione", "il poeta resta fuori dalla casa"), C("", "Tombe e fiori", "profumo di vita e di morte")]),
 S("L'alba", "L'alba conclude il processo. I petali del gelsomino si chiudono sgualciti, e custodiscono il segreto di una nuova vita che sta per nascere. La poesia ci lascia un'immagine di fecondità, che il poeta non vivrà. Un tema decisivo è l'opposizione tra la casa nuziale e il nido. Da una parte la nuova famiglia, dall'altra la famiglia dei morti, a cui lui resta legato in modo ossessivo.",
   [C("", "La nuova vita", "i petali custodiscono il segreto"), C("", "Casa nuziale e nido", "il legame ossessivo con i morti")])]))
X.append(AN("AN7b", 2, 4, "scheda", "Italy e l'emigrazione", [
 S("Il nido spezzato", "Tra i Poemetti ce n'è uno molto importante. Si intitola Italy. Parla dell'emigrazione degli italiani in America. È una poesia sulla modernità e sullo strappo dal nido. Anche qui l'emigrato è un simbolo. Chi parte si stacca dalla sua vecchia vita per iniziarne una nuova. Questo ci riporta al tema che ci ha accompagnato per tutta la lezione: il nido, la famiglia, la terra.",
   [C("", "Italy", "poemetto sull'emigrazione in America"), C("", "Lo strappo dal nido", "chi parte lascia la vecchia vita")]),
 S("Il tardo Pascoli", "Nell'ultima fase Pascoli si dedica alla poesia civile e alle opere dotte. I Poemi conviviali e i Carmina in latino. Una ricca attività di saggista, soprattutto su Dante. Muore nel millenovecentododici. Il docente ricorda che il Pascoli maturo è forse meno interessante dei testi di Myricae. Ma è utile conoscerlo per capire la vastità e la modernità dell'autore.",
   [C("", "Poesia civile", "Poemi conviviali e Carmina"), C("1912", "La morte", "dopo una lunga carriera")])]))
X.append(AN("AN1c", 1, 1, "scheda", "Il delitto del 10 agosto 1867", [
 S("Che cosa accadde", "Fermiamoci sul fatto che ha cambiato la vita di Pascoli. Il padre, Ruggero, amministra dei terreni per il principe Torlonia. È una specie di intermediario. Il dieci agosto del milleottocentosessantasette viene assassinato con un colpo d'arma da fuoco alle spalle. Pascoli ha undici anni. La famiglia perde la fonte di sostentamento. La madre e i figli restano sconvolti.",
   [C("", "Ruggero Pascoli", "amministra terreni per il principe Torlonia"), C("10 agosto 1867", "L'omicidio", "colpo d'arma da fuoco alle spalle")]),
 S("Un mistero", "Chi è stato? Non lo sapremo mai. La polizia fece indagini, ma non capì chi avesse sparato. Si pensò a un contadino scontento. Si pensò a un debitore che non voleva restituire i soldi. Si pensò a una vendetta. Non si è mai capito il movente, né il mandante, né l'esecutore. Il dubbio che resta senza risposta tormenterà Pascoli per tutta la vita.",
   [C("", "Le ipotesi", "un contadino, un debitore, una vendetta"), C("", "Nessuna risposta", "né movente né colpevole")]),
 S("Una catena di lutti", "Il delitto avvia una catena di lutti familiari. Muore la madre. Muore la sorella maggiore. Muoiono alcuni fratelli. Restano Pascoli e due sorelle. Il giovane era già sensibile, e ne rimane segnato per sempre. Il docente lo ripete: la componente biografica è fondamentale per capire la sua psiche e la sua produzione letteraria. Non si può leggere Pascoli senza ricordare quel dieci agosto.",
   [C("", "I lutti", "la madre, la sorella e i fratelli"), C("", "Un segno per la vita", "la biografia spiega la poesia")])]))
X.append(AN("AN3c", 1, 3, "scheda", "Pascoli nella poesia di fine Ottocento", [
 S("Un uomo dell'Ottocento", "Collochiamo Pascoli nel suo tempo. Nasce prima dell'unità d'Italia, nel milleottocentocinquantacinque. Prima di D'Annunzio, quindi. È un uomo prevalentemente del secondo Ottocento, e il Novecento lo vedrà solo in parte. Ha vissuto da piccolo l'Italia unita. Il suo percorso passa dentro la poesia decadente e la poesia di fine secolo.",
   [C("1855", "Nasce prima di D'Annunzio", "prima dell'unità d'Italia"), C("", "Secondo Ottocento", "il Novecento lo vedrà poco")]),
 S("Simbolismo, non estetismo", "Pascoli è influenzato dal simbolismo, e dal Decadentismo. Ma non aderisce all'estetismo. Il Decadentismo produce effetti anche in Italia, ma in modi diversi a seconda degli autori. Non troveremo nulla di estetico, di magniloquente o di enfatico. Nemmeno di erotico, se non qualche accenno nel Gelsomino notturno, che vedremo. Pascoli, dice il docente, scrive piuttosto chiaramente. Forse più chiaramente di D'Annunzio.",
   [C("", "Simbolismo", "gli oggetti alludono a un altro significato"), C("", "Niente estetismo", "stile semplice, chiaro, non enfatico")]),
 S("Perché studiarlo", "Pascoli è un autore molto richiesto all'esame. Per questo ne approfondiamo la biografia, la poetica e molti testi. Ma non sarà una lezione particolarmente difficile. Il suo stile è semplice. In lui c'è molta contemporaneità della sua epoca, molta modernità. A metà tra il Decadentismo, le sue tristezze, la vita e il simbolismo.",
   [C("", "Autore importante", "richiesto agli esami"), C("", "Modernità", "tra Decadentismo e simbolismo")])]))
ANS.extend(X)
